parameters.text:
=Meeting request: {{ $('When Called by Orchestrator').item.json.request }}

Current date/time: {{ $now.toISO() }} ({{ $now.format('cccc') }})

Existing busy events for the next 7 days (raw Google Calendar data, may be an empty array if the calendar is free):
{{ JSON.stringify($json.busyEvents) }}

=New meeting request (raw text): {{ $('When Called by Orchestrator').item.json.request }}

Proposed new meeting: "{{ $json.output.title }}" ({{ $json.output.startTime }} - {{ $json.output.endTime }}), attendees: {{ $json.output.attendees.join(', ') || 'none listed' }}

Conflicting existing event(s):
{{ JSON.stringify($json.output.conflictingEvents) }}

All busy events in the 7-day search window (use this to find genuinely free alternative slots):
{{ JSON.stringify($('Combine Into One List').item.json.busyEvents) }}

Current date/time: {{ $now.toISO() }} ({{ $now.format('cccc') }})

parameters.jsCode:
const item = $input.item.json;
let output = { ...item.output };
const rawRequest = ($('When Called by Orchestrator').item.json.request || '');
const busyEvents = $('Combine Into One List').item.json.busyEvents || [];

// 1. Attendees: union of whatever the model found plus any email addresses actually in the text
const foundEmails = [...new Set((rawRequest.match(/[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}/g) || []))];
const modelEmails = Array.isArray(output.attendees) ? output.attendees : [];
output.attendees = [...new Set([...modelEmails, ...foundEmails])];

// 2. Title: prefer an explicit "subject:"/"title:" marker in the text; else keep the model's
//    non-empty title; else fall back to a visible placeholder (never leave it truly blank)
const subjectMatch = rawRequest.match(/(?:subject|title)\s*[:\-]\s*"?([^".\n]+)"?/i);
if (subjectMatch && subjectMatch[1] && subjectMatch[1].trim()) {
  output.title = subjectMatch[1].trim();
} else if (!output.title || !output.title.trim()) {
  output.title = 'Meeting';
}

// 3. Exact time: if the text names a clock time, trust that over the model's time-of-day
//    (keep the model's resolved DATE - relative-date resolution stays the LLM's job)
const timeMatch = rawRequest.match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i);
let startDt = DateTime.fromISO(output.startTime);
if (timeMatch && startDt.isValid) {
  let hour = parseInt(timeMatch[1], 10);
  const minute = timeMatch[2] ? parseInt(timeMatch[2], 10) : 0;
  const meridiem = timeMatch[3].toLowerCase();
  if (meridiem === 'pm' && hour < 12) hour += 12;
  if (meridiem === 'am' && hour === 12) hour = 0;
  startDt = startDt.set({ hour, minute, second: 0, millisecond: 0 });
  output.requestedExactTime = true;
}

// 4. Duration: if the text states an explicit duration, trust that over the model's duration
let durationMinutes = null;
const durMatch = rawRequest.match(/(\d+(?:\.\d+)?)\s*(hour|hr|hours|minute|min|minutes)/i);
if (durMatch) {
  const n = parseFloat(durMatch[1]);
  durationMinutes = /hour|hr/i.test(durMatch[2]) ? n * 60 : n;
} else if (output.startTime && output.endTime) {
  const s = DateTime.fromISO(output.startTime);
  const e = DateTime.fromISO(output.endTime);
  if (s.isValid && e.isValid) durationMinutes = e.diff(s, 'minutes').minutes;
}
if (!durationMinutes || durationMinutes <= 0) durationMinutes = 30;

const endDt = startDt.plus({ minutes: durationMinutes });
output.startTime = startDt.toISO();
output.endTime = endDt.toISO();

// 5. Re-run conflict detection in code, against the real busy list, for the corrected window -
//    this no longer depends on the model having judged the (possibly wrong) time it originally picked
const overlaps = busyEvents.filter(ev => {
  const evStart = DateTime.fromISO(ev.start && ev.start.dateTime);
  const evEnd = DateTime.fromISO(ev.end && ev.end.dateTime);
  if (!evStart.isValid || !evEnd.isValid) return false;
  return startDt < evEnd && endDt > evStart;
});

if (overlaps.length > 0) {
  output.hasConflict = true;
  output.foundSlot = false;
  output.conflictingEvents = overlaps.map(ev => ({
    title: ev.summary || '(untitled event)',
    start: ev.start.dateTime,
    end: ev.end.dateTime,
  }));
} else if (output.requestedExactTime) {
  output.hasConflict = false;
  output.foundSlot = true;
  output.conflictingEvents = [];
}
// If this was never an exact-time request and no explicit time was found in the text, the model's
// own flexible-search result (hasConflict/foundSlot/conflictingEvents) is left untouched.

return { json: { ...item, output } };
